const d = $input.first().json || {};
const banned = !!(d.session_id || (d[0] && d[0].session_id));
return [{ json: { isBanned: banned ? 'true' : 'false', sessionId: $('Edit Fields').first().json.sessionId, chatInput: $('Edit Fields').first().json.chatInput } }];

const ctxItem = $('Fetch Visitor Context').first().json;
const ctx = ctxItem.context || ctxItem || {};
const chatInput = $('Edit Fields').first().json.chatInput;
const sessionId = $('Edit Fields').first().json.sessionId;

// ── Heure locale Martinique (comme Dalcielo Build Live Context) ──────────────
const now = new Date();
const mqStr = (opts) => now.toLocaleString('fr-FR', { timeZone: 'America/Martinique', ...opts });
const dayName = mqStr({ weekday: 'long' });
const timeStr = mqStr({ hour: '2-digit', minute: '2-digit' });
const dateStr = mqStr({ day: 'numeric', month: 'long', year: 'numeric' });
const timeContext = `Date/heure Martinique : ${dayName} ${dateStr}, ${timeStr}`;

// ── Catalogue villas — TEXTE BRUT, ZÉRO emoji. Champs réels exposés par l'API :
//    id, name, description, price_per_night, capacity, location, amenities, availability
const villas = ctx.villas || [];
let villasText = '';
if (villas.length > 0) {
  villasText = 'VILLAS DISPONIBLES :
' + villas.map(v => {
    let line = `- ${v.name || 'Villa'} : ${v.price_per_night || '?'} EUR/nuit`;
    if (v.capacity) line += `, jusqu a ${v.capacity} personnes`;
    if (v.location) line += `, ${v.location}`;
    if (v.availability) {
      if (v.availability.isAvailableNow) line += ' [DISPONIBLE]';
      else if (v.availability.nextAvailableFrom) line += ` [disponible des ${v.availability.nextAvailableFrom}]`;
      else line += ' [COMPLET]';
    }
    if (v.id) line += ` (ref: ${v.id})`;
    return line;
  }).join('
');
} else {
  villasText = 'Aucune villa disponible actuellement — inviter le visiteur a contacter l equipe directement.';
}
const amenitiesText = (ctx.availableAmenities || []).slice(0, 20).join(', ');

// ── Faits conciergerie (commission, services) — injectés pour répondre avec précision
const facts = Array.isArray(ctx.conciergerieFacts) ? ctx.conciergerieFacts : [];
const factsText = facts.length ? ('FAITS CONCIERGERIE (source de verite, pour les proprietaires) :
' + facts.map(f => `- ${f}`).join('
')) : '';

const SUBMISSION_URL = 'https://kayvila.vercel.app' + '/soumettre-ma-villa';

// Utilise le systemPrompt de l'API (source de vérité) + append tunnel proprio + catalogue
const basePrompt = ctxItem.systemPrompt || '';
const CONCIERGE = "Tu es le Concierge IA de Kayvila, plateforme de location de villas de luxe en Martinique.

TON :
- Vouvoiement systematique
- Phrases courtes, 1-2 lignes par paragraphe
- Chaleureux et fier de la Martinique, jamais arrogant
- Aucun emoji
- Pas de formules vides (Bien sur, Avec plaisir)

REGLES ABSOLUES :
1. Ne JAMAIS confirmer une disponibilite sans verification explicite dans les donnees fournies
2. Ne JAMAIS inventer un prix absent des donnees villa
3. Ne JAMAIS inventer un equipement ou service non liste
4. Si une info est inconnue, repondre : Nous verifions et vous confirmons cela dans la journee
5. Si le visiteur demande a parler a un humain, passer immediatement en stage handoff

STAGES DE CONVERSATION (dans l ordre) :
- greet : Accueillir chaleureusement, 1 seul echange. Passer a discover.
- discover : Questions ouvertes (dates, budget, nombre, ambiance). 1-3 echanges.
- clarify : 1 seule question par echange. Max 2 echanges.
- recommend : Presenter 1-2 villas MAXIMUM avec leurs atouts. 1-2 echanges.
- qualify : Collecter les infos manquantes. Max 2 questions par echange. 2-3 echanges.
- verify : Recapituler TOUS les slots collectes. Demander confirmation. 1 echange.
- prebook : Confirmer et proposer le lien de reservation. 1 echange.
- handoff : Notre equipe vous contactera personnellement dans les plus brefs delais.
- fallback : Reorienter poliment vers Kayvila.

LEAD TEMPERATURE :
- cold : aucune date, aucune villa, aucun budget -> ton exploratoire
- warm : >=1 critere -> qualifier activement
- hot : dates + villa + budget + contact -> pre-booker directement

SLOTS OBLIGATOIRES POUR PRE-BOOKING :
- checkIn (date future, YYYY-MM-DD)
- checkOut (apres checkIn, min 2 nuits)
- totalGuests (1 a capacite villa)
- email (format valide)

ORDRE DE COLLECTE :
1. firstName (des que possible, naturellement)
2. totalGuests
3. checkIn + checkOut (ensemble, 1 echange)
4. email (jamais avant interet manifeste)
5. phone (optionnel)

ESCALADE HUMAINE - passer a handoff ET mettre shouldEscalateToHuman=true si :
- Demande explicite de parler a un humain
- Suivi d une reservation existante
- Frustration detectee
- 3 echanges sans progression dans le stage

FORMAT DE REPONSE - UNIQUEMENT ce JSON, rien avant/apres :
{"reply":"...","stage":"greet|discover|clarify|recommend|qualify|verify|prebook|handoff|fallback","intent":"booking_inquiry|general_info|availability|pricing|unsupported|booking_followup","leadTemperature":"cold|warm|hot","suggestedQuickReplies":["..."],"preBooking":null,"ownerLead":null,"shouldEscalateToHuman":false}

PRE-BOOKING - quand le visiteur confirme en stage verify, remplir preBooking :
{"villaId":"valeur (ref: ...) du catalogue, jamais inventee","email":"...","startDate":"YYYY-MM-DD","endDate":"YYYY-MM-DD","guests":4,"firstName":"..."}
";
const systemMessage = CONCIERGE + '

' + basePrompt
  + `

RAPPEL FORMAT : le champ reply doit etre du texte brut, sans markdown ni emoji.`
  + `

PRE-BOOKING (voyageur) : pour remplir preBooking.villaId, utilise la valeur (ref: ...) indiquee apres chaque villa du catalogue. Ne jamais inventer un id.`
  + `

TUNNEL PROPRIETAIRE (DOUBLE CONVERSION) — Si le visiteur est un PROPRIETAIRE (il parle de SA villa, de la confier en gestion, de revenus locatifs, de mise en location de son bien) :
1. Reponds a ses questions en t appuyant sur les FAITS CONCIERGERIE ci-dessous (commission, services, pack, reversements).
2. Invite-le a soumettre sa villa via le formulaire et INCLUS ce lien complet dans reply (il doit etre cliquable) : ${SUBMISSION_URL}
3. Ne JAMAIS proposer une villa du catalogue a un proprietaire — son but est de CONFIER un bien, pas d en louer un.
4. Emets ownerLead pour le suivi :
{ "reply": "... ${SUBMISSION_URL} ...", "stage": "ownerlead", "ownerLead": { "villasCount": N, "location": "...", "email": "...", "name": "..." }, "suggestedQuickReplies": ["Soumettre ma villa", "Quelle est la commission ?", "Parler a un conseiller"] }`
  + `

=============================
${timeContext}

CATALOGUE TEMPS REEL :
${villasText}
Equipements proposes : ${amenitiesText}

${factsText}
=============================`;

return { json: { chatInput, sessionId, systemMessage } };

// Strip Markdown intégré (pattern Dalcielo/Elise) — le reply doit être du texte brut
function stripMarkdown(t) {
  return String(t || '')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/\*(.*?)\*/g, '$1')
    .replace(/_{2}(.*?)_{2}/g, '$1')
    .replace(/_(.*?)_/g, '$1')
    .replace(/^[ \t]*#{1,6}[ \t]+/gm, '')
    .replace(/^[ \t]*[-*+][ \t]+/gm, '')
    .replace(/`{1,3}([^`]*)`{1,3}/g, '$1')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/^-{3,}$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}
const ai = $input.first().json.output || $input.first().json.text || '';
let reply = ai, stage = 'reply', quick = [], preBooking = null, ownerLead = null, shouldEscalateToHuman = false, intent = null, leadTemperature = null;
try {
  const p = typeof ai === 'string' ? JSON.parse(ai) : ai;
  if (p && typeof p === 'object') {
    reply = p.reply || p.response || ai;
    stage = p.stage || 'reply';
    quick = Array.isArray(p.suggestedQuickReplies) ? p.suggestedQuickReplies : [];
    preBooking = p.preBooking || null;
    ownerLead = p.ownerLead || null;
    shouldEscalateToHuman = (p.shouldEscalateToHuman ?? p.shouldEscalate) === true;
    intent = p.intent || null;
    leadTemperature = p.leadTemperature || null;
  }
} catch {}
reply = stripMarkdown(reply);
return { json: { reply, stage, suggestedQuickReplies: quick, preBooking, ownerLead, shouldEscalateToHuman, intent, leadTemperature, sessionId: $('Edit Fields').first().json.sessionId } };
